<div style="margin-top:18px">@foreach($roles as $role)<details class="panel role-panel"><summary class="record-summary"><div><strong>{{ $role->name }}</strong><span>{{ $role->code }} · {{ $role->users_count }} users · {{ $role->permissions->count() }} permissions</span></div><div>@if($role->is_system)<span class="status-pill locked">SYSTEM</span>@endif<span class="status-pill {{ $role->is_active?'active':'closed' }}">{{ $role->is_active?'ACTIVE':'INACTIVE' }}</span></div></summary>@if($role->code==='SUPER_ADMIN')<div class="record-body"><div class="callout warn"><strong>Super Admin is unrestricted.</strong> It bypasses the permission matrix and cannot be reduced.</div></div>@else<form method="POST" action="{{ route('administration.roles.update',$role) }}" class="record-body">@csrf @method('PUT')<div class="form-grid"><label><span>Role Name</span><input name="name" value="{{ $role->name }}" required></label><label class="check-row"><input type="checkbox" name="is_active" value="1" {{ $role->is_active?'checked':'' }}><span>Active role</span></label><label class="span-2"><span>Description</span><input name="description" value="{{ $role->description }}"></label></div><div class="permission-matrix">@foreach($permissionGroups as $module=>$permissions)<div class="permission-group"><h4>{{ $module }}</h4>@foreach($permissions as $p)<label><input type="checkbox" name="permission_ids[]" value="{{ $p->id }}" {{ $role->permissions->contains($p->id)?'checked':'' }}><span><b>{{ $p->name }}</b><small>{{ $p->key }}</small></span></label>@endforeach</div>@endforeach</div><div class="form-actions"><button class="btn btn-primary">Save Role Permissions</button></div></form>@endif</details>@endforeach</div>
